/* 일망호 대기방 표식 — images/normal/20261104202815~26의 원본 해상도 PNG 조각.
   다른 이미지 라이브러리로 미리 계산한 해시를 쓰지 않는다. 기준 이미지와 공유 프레임
   모두 VMH.ImgHash.dHashFromCanvas로 계산하여 브라우저의 보간 차이를 없앤다.
   데이터는 두 고정 표식뿐이며 닉네임·방 이름은 포함하지 않는다. */
(function (global) {
    'use strict';
    const marks = [{"rect":[170,28,310,78],"maxDistance":24,"sources":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"]},{"rect":[860,40,170,65],"maxDistance":32,"sources":["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"]}];
    const { cropToCanvas, dHashFromCanvas, popcnt32 } = global.VMH.ImgHash;
    let loaded = false, error = null;
    const cache = new Map();
    const loadImage = src => new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => resolve(img);
        img.onerror = () => reject(new Error('일망호 대기방 기준 이미지 로딩 실패'));
        img.src = src;
    });
    const ready = Promise.all(marks.map(async mark => {
        mark.images = await Promise.all(mark.sources.map(loadImage));
        delete mark.sources;
    })).then(() => { loaded = true; }, e => { error = e.message; console.error('[GeneralLobby]', e); });

    function reference(mark, W, H) {
        const [x, y, w, h] = mark.rect;
        const width = Math.max(1, Math.round(w * W / 2560));
        const height = Math.max(1, Math.round(h * H / 1440));
        const canvas = document.createElement('canvas');
        canvas.width = width; canvas.height = height;
        const ctx = canvas.getContext('2d');
        const hashes = mark.images.map(img => {
            ctx.clearRect(0, 0, width, height);
            ctx.drawImage(img, 0, 0, width, height);
            return dHashFromCanvas(canvas);
        });
        // 4장의 서로 다른 배경에서 변하지 않은 비트만 표식으로 쓴다.
        const mask = hashes[0].map((word, i) => {
            let same = 0xffffffff;
            for (const hash of hashes.slice(1)) same &= ~(word ^ hash[i]);
            return same >>> 0;
        });
        return { mask, bits: hashes[0].map((word, i) => (word & mask[i]) >>> 0),
                 stableBits: mask.reduce((n, word) => n + popcnt32(word), 0) };
    }

    function read(frame, W, H) {
        if (!loaded || !frame || !W || !H) return { ready: loaded, match: false, error };
        const key = W + 'x' + H;
        if (!cache.has(key)) {
            if (cache.size >= 4) cache.clear();
            cache.set(key, marks.map(mark => reference(mark, W, H)));
        }
        const refs = cache.get(key);
        const results = marks.map((mark, k) => {
            const [x, y, w, h] = mark.rect, ref = refs[k];
            const hash = dHashFromCanvas(cropToCanvas(frame, x * W / 2560, y * H / 1440, w * W / 2560, h * H / 1440));
            const distance = hash.reduce((n, word, i) => n + popcnt32((word ^ ref.bits[i]) & ref.mask[i]), 0);
            return { distance, limit: mark.maxDistance, stableBits: ref.stableBits,
                     match: ref.stableBits >= 64 && distance <= mark.maxDistance };
        });
        return { ready: true, match: results.every(result => result.match), markers: results };
    }
    global.VMH.GeneralLobby = { read, ready };
})(window);
